<?php
require_once __DIR__.'/includes/module.php';
require_roles(['admin','staff']);
$page_title='Sertifikat Peserta';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$registration=(int)$_POST['registration_id'];$number=trim($_POST['certificate_number']);$issue=$_POST['issue_date'];$grade=trim($_POST['grade']??'');
try{$s=$pdo->prepare('INSERT INTO certificates(registration_id,certificate_number,issue_date,grade,issued_by) VALUES(?,?,?,?,?)');$s->execute([$registration,$number,$issue,$grade,$_SESSION['user']['id']]);flash('Nomor sertifikat berhasil dicatat.');}catch(PDOException $e){flash('Gagal menyimpan. Pendaftaran mungkin sudah memiliki sertifikat atau nomor sudah dipakai.');}header('Location: certificates.php');exit;}
$eligible=module_list($pdo,"SELECT r.id,p.name,t.title FROM registrations r JOIN participants p ON p.id=r.participant_id JOIN trainings t ON t.id=r.training_id LEFT JOIN certificates c ON c.registration_id=r.id WHERE c.id IS NULL AND r.status IN ('Terdaftar','Terverifikasi')");
$rows=module_list($pdo,"SELECT c.*,p.name,t.title FROM certificates c JOIN registrations r ON r.id=c.registration_id JOIN participants p ON p.id=r.participant_id JOIN trainings t ON t.id=r.training_id ORDER BY c.issue_date DESC");
require __DIR__.'/includes/header.php';show_flash();?>
<section class="panel"><div class="panel-head"><h3>Catat Penerbitan Sertifikat</h3></div><?php if(!$eligible):?><div class="notice">Belum ada pendaftaran yang dapat diterbitkan sertifikatnya.</div><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field full"><label>Peserta dan Pelatihan</label><select name="registration_id" required><?php foreach($eligible as $r):?><option value="<?=$r['id']?>"><?=e($r['name'].' — '.$r['title'])?></option><?php endforeach;?></select></div><div class="field"><label>Nomor Sertifikat</label><input name="certificate_number" required></div><div class="field"><label>Tanggal Terbit</label><input type="date" name="issue_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Nilai / Predikat (opsional)</label><input name="grade"></div></div><div class="form-actions"><button class="btn">Simpan Sertifikat</button></div></form><?php endif;?></section>
<section class="panel"><div class="panel-head"><h3>Register Sertifikat</h3></div><table><thead><tr><th>No. Sertifikat</th><th>Peserta</th><th>Pelatihan</th><th>Tanggal Terbit</th><th>Predikat</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">Belum ada sertifikat.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e($r['certificate_number'])?></td><td><?=e($r['name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['issue_date'])?></td><td><?=e($r['grade'])?></td></tr><?php endforeach;?></tbody></table></section>
<?php require __DIR__.'/includes/footer.php';?>
